{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Absolute oral bioavailability of GSK269984A in healthy human volunteers was 95% after a 100 µg oral vs i.v. microdose, directly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Oral administration of GSK269984A as a solution in humans produced systemic exposure approaching the i.v. dose, with estimated bioavailability in excess of 94%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Human oral and i.v. microdose data for GSK269984A indicate rapid absorption and high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A non-experimental prediction suggested low oral bioavailability for GSK269984A (~10%), but this is contradicted by direct human absolute bioavailability measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct human absolute bioavailability data for GSK269984A show F ≈95% and >94%, well above the 20% threshold, and all retrieved experimental molecules have F ≥20%. The physicochemical low-F prior is overridden by these direct measurements.",
  "evidence_gaps": [
    "The query's identity relative to GSK269984A is not explicitly confirmed because SMILES are omitted.",
    "No direct dose-response or food-effect data are provided for the query.",
    "The only low-bioavailability record is a non-experimental prediction rather than a measured value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

